# R golden fixtures for gaply_core's scale scores (Research OS, Phase 8M,
# decision 409, capability stats.prepare.scale_score).
#
# Run by its full path, from anywhere:
#
#   /usr/local/bin/Rscript make_prep_fixtures.R
#
# R is the reference, run outside Gaply (ADR-008): base R only, nothing of it
# copied into Gaply.
#
# Writes, next to this script:
#   * data_*.csv: one synthetic dataset per file (a two-line '#' header, then
#     `id,<items>`), each READ BACK with read.csv and everything computed on
#     what was read;
#   * cells_bits.csv: the IEEE 754 bits of every number R read (ADR-008 s3);
#   * cases.tsv: each case's file, items (headers, in column order), the items
#     reversed, the scale's ends ("min max", or "-"), the statistic, the rule
#     ("every_item" or "at_least n") and the missing codes;
#   * rows.tsv: the score of every row of every case, as %.17g, "NA" when the
#     row has none, "Inf" where R's total does not fit a double;
#     for the 100,000-row cases, every 100th row;
#   * counts.tsv: each case's four counts, and the sum of the 1-based numbers
#     of its scored rows, so which rows are scored is checked on the big cases
#     too;
#   * refused.tsv: each case Gaply must refuse, its closed code, and R's
#     answer's size where R computes (ADR-008 s4);
#   * summary.tsv: R's n, mean, sd, min and max of a score column, for the
#     descriptive summary's check;
#   * measurements.txt: what this script measured.
#
# The calls, as ADR-011 Part 13 gives them, on a matrix X of what was read,
# after the codes are removed and the reversal applied:
#
#   valid <- rowSums(!is.na(X))
#   score <- ifelse(valid >= n, rowSums(X, na.rm = TRUE), NA)
#   score <- ifelse(valid >= n, rowMeans(X, na.rm = TRUE), NA)
#
# rowSums gives 0 and rowMeans NaN on an empty row, which is why the rule is
# applied first. A value x of a reversed item is min + max - x. rowMeans is the
# total over the count here, with no second pass; Gaply's mean is
# stats_verify::mean, which has one, so the test counts the rows that differ.
#
# The 100,000-row cases have no CSV: row i (0-based), item j (1 to 5) is
# ((i * 7919 * j) mod 10007) / 100 + ((i * 104729) mod 1009) / 50, and empty
# when (i * (j + 3)) mod 101 is 0: the same IEEE operations on both sides, so
# the doubles are equal; gaply_core's golden builds it from this formula too.
# The near-overflow cases are built by formula on both sides too (see there).

HEADER <- c(
  "# Synthetic data for gaply_core's scale score R golden fixtures (Research OS, Phase 8M).",
  "# Generated by /usr/local/bin/Rscript make_prep_fixtures.R (do not edit by hand)."
)
OUT <- "# written by: /usr/local/bin/Rscript make_prep_fixtures.R"
VERSION <- sprintf(
  "# %s, %s, sizeof.longdouble %d",
  R.version.string, R.version$arch, .Machine$sizeof.longdouble
)

args <- commandArgs(trailingOnly = FALSE)
here <- dirname(normalizePath(sub("^--file=", "", args[grep("^--file=", args)])))
path <- function(f) file.path(here, f)
num <- function(v) sprintf("%.17g", v)

TOKENS <- c("", "NA", "N/A", ".", "NULL")

cell_bits <- list()
bits_hex <- function(x) paste(as.character(writeBin(as.numeric(x), raw(), size = 8, endian = "big")), collapse = "")

# `m` is a character matrix with column names: the cells as written.
write_data <- function(file, m, id = TRUE) {
  con <- file(path(file), "w")
  writeLines(HEADER, con)
  writeLines(paste(c(if (id) "id", colnames(m)), collapse = ","), con)
  for (r in seq_len(nrow(m))) writeLines(paste(c(if (id) r, m[r, ]), collapse = ","), con)
  close(con)
  back <- read.csv(path(file), comment.char = "#", na.strings = TOKENS, check.names = FALSE)
  if (id) back <- back[, -1, drop = FALSE]
  for (j in seq_along(back)) {
    v <- as.numeric(back[[j]])
    for (i in which(!is.na(v))) {
      cell_bits[[length(cell_bits) + 1]] <<- sprintf("%s,%d,%s,%s", file, i, names(back)[j], bits_hex(v[i]))
    }
  }
  back
}

as_cells <- function(df) {
  m <- matrix("", nrow(df), ncol(df), dimnames = list(NULL, names(df)))
  for (j in seq_along(df)) {
    v <- df[[j]]
    m[, j] <- ifelse(is.na(v), "", format(v, digits = 15, trim = TRUE, drop0trailing = TRUE, scientific = FALSE))
  }
  m
}

likert <- function(v, lo = 1, hi = 5) pmin(hi, pmax(lo, round(v)))

# ---- the data ---------------------------------------------------------------

set.seed(20261102)
data <- list()

{
  n <- 60
  t <- rnorm(n)
  q <- function(sign = 1) {
    v <- likert(3 + sign * 1.1 * t + rnorm(n, 0, 0.8))
    v[sample(n, 6)] <- NA
    v
  }
  data$likert <- write_data("data_likert.csv", as_cells(data.frame(
    q1 = q(), q2 = q(-1), q3 = q(), q4 = q(), q5 = q(-1), q6 = q()
  )))
}
{
  n <- 30
  v <- function() {
    x <- sample(0:10, n, replace = TRUE)
    x[1] <- 0
    x[2] <- 10
    x
  }
  data$zero_ten <- write_data("data_zero_ten.csv", as_cells(data.frame(a = v(), b = v(), c = v())))
}
{
  # Fractional values on and inside the fractional, negative ends -2.5 and 3.75.
  n <- 40
  v <- function() {
    x <- round(runif(n, -2.5, 3.75), 3)
    x[1] <- -2.5
    x[2] <- 3.75
    x[sample(3:n, 4)] <- NA
    x
  }
  data$frac <- write_data("data_frac.csv", as_cells(data.frame(f1 = v(), f2 = v(), f3 = v(), f4 = v())))
}
{
  # Likert items with tokens, codes inside and outside the ends.
  n <- 40
  v <- function() {
    x <- as.character(likert(3 + rnorm(n, 0, 1.2)))
    x[sample(n, 3)] <- "99"
    x[sample(n, 3)] <- "-9"
    x[sample(n, 4)] <- sample(TOKENS, 4, replace = TRUE)
    x
  }
  m <- cbind(c1 = v(), c2 = v(), c3 = v())
  data$codes <- write_data("data_codes.csv", m)
}
{
  # Rows with exactly 0, 1, 2, 3 and 4 values among 4 items, in every place.
  m <- as.matrix(expand.grid(rep(list(c(FALSE, TRUE)), 4)))
  vals <- matrix(sample(1:5, length(m), replace = TRUE), nrow(m), 4)
  cells <- matrix("", nrow(m), 4, dimnames = list(NULL, sprintf("v%d", 1:4)))
  cells[m] <- as.character(vals[m])
  data$counted <- write_data("data_counted.csv", cells)
}
{
  n <- 12
  data$two <- write_data("data_two.csv", as_cells(data.frame(
    x = c(NA, round(rnorm(n - 1, 10, 3), 2)),
    y = c(round(rnorm(n - 1, 5, 1), 2), NA)
  )))
}
{
  wide <- function(k, n) {
    m <- matrix(sample(1:5, n * k, replace = TRUE), n, k, dimnames = list(NULL, sprintf("w%03d", seq_len(k))))
    cells <- matrix(as.character(m), n, k, dimnames = dimnames(m))
    cells[sample(length(cells), n)] <- ""
    cells
  }
  # No id column here: 127 items are the whole 127-column file, and 128 items
  # the whole 128-column file, which leaves no room for the score.
  data$k127 <- write_data("data_k127.csv", wide(127, 30), id = FALSE)
  data$k128 <- write_data("data_k128.csv", wide(128, 10), id = FALSE)
}
{
  # Near overflow, with no CSV: built by formula on both sides, as the big
  # cases are, because R's decimal parser cannot be given these doubles. Of 170
  # spellings from 10e306 to 179e306 R read none to the double a correct
  # parser reads (measured 2 Nov 2026 against /usr/bin/printf %a), and it read
  # 8.9884656743115795e+307 back as another double than 2^1023.
  # Row by row, in column order, a = 2^1023, d = 2^1022, c = 1.5 * 2^1023 + 2^1021:
  #   1: a + d, a total that fits, near the top;
  #   2: c + c, a total that does not fit;
  #   3, 4: the same, negative;
  #   5: c + c - c, a partial total that overflows though the true total fits;
  #   6: c - c - c, fits in sum and mean, and the mean's second pass overflows
  #      (x - m);
  #   7: ordinary.
  a <- 2^1023
  d <- 2^1022
  c <- 1.5 * 2^1023 + 2^1021
  data$overflow <- data.frame(
    o1 = c(a, c, -a, -c, c, c, 1),
    o2 = c(d, c, -d, -c, c, -c, 2),
    o3 = c(NA, NA, NA, NA, -c, -c, 3)
  )
}
{
  # Conditioning: a large offset, and a total that cancels.
  n <- 25
  base <- 1e9 + round(rnorm(n), 3)
  data$offset <- write_data("data_offset.csv", as_cells(data.frame(
    p1 = base, p2 = base + round(rnorm(n), 3), p3 = base + round(rnorm(n), 3)
  )))
  big <- round(rnorm(n, 0, 1e6), 3)
  data$cancel <- write_data("data_cancel.csv", as_cells(data.frame(
    m1 = big, m2 = round(rnorm(n, 0, 1e-3), 6), m3 = -big
  )))
}
{
  # Nothing can be scored by every item.
  data$no_row <- write_data("data_no_row.csv", cbind(
    a = c("1", "", "3", ""),
    b = c("", "2", "", "")
  ))
}

big_table <- function() {
  i <- 0:99999
  base <- ((i * 104729) %% 1009) / 50
  m <- sapply(1:5, function(j) ((i * 7919 * j) %% 10007) / 100 + base)
  for (j in 1:5) m[(i * (j + 3)) %% 101 == 0, j] <- NA
  colnames(m) <- sprintf("b%d", 1:5)
  as.data.frame(m)
}
data$big <- big_table()

# ---- the cases --------------------------------------------------------------

case <- function(name, file, key, items, reversed = character(), scale = NULL,
                 statistic = "sum", rule = "every_item", codes = numeric(),
                 refused = NULL) {
  list(name = name, file = file, key = key, items = items, reversed = reversed,
       scale = scale, statistic = statistic, rule = rule, codes = codes,
       refused = refused)
}

Q <- sprintf("q%d", 1:6)
Q4 <- sprintf("v%d", 1:4)
FS <- sprintf("f%d", 1:4)
CS <- sprintf("c%d", 1:3)
BS <- sprintf("b%d", 1:5)

cases <- list(
  case("likert_sum_every", "data_likert.csv", "likert", Q),
  case("likert_mean_every", "data_likert.csv", "likert", Q, statistic = "mean"),
  case("likert_sum_at_1", "data_likert.csv", "likert", Q, rule = "at_least 1"),
  case("likert_mean_at_1", "data_likert.csv", "likert", Q, statistic = "mean", rule = "at_least 1"),
  case("likert_sum_at_top", "data_likert.csv", "likert", Q, rule = "at_least 5"),
  case("likert_mean_at_top", "data_likert.csv", "likert", Q, statistic = "mean", rule = "at_least 5"),
  case("likert_mean_at_3", "data_likert.csv", "likert", Q, statistic = "mean", rule = "at_least 3"),
  case("rev_1to5_sum", "data_likert.csv", "likert", Q, c("q2", "q5"), c(1, 5)),
  case("rev_1to5_mean_at_4", "data_likert.csv", "likert", Q, c("q2", "q5"), c(1, 5), "mean", "at_least 4"),
  case("rev_0to10_sum", "data_zero_ten.csv", "zero_ten", c("a", "b", "c"), c("a", "c"), c(0, 10)),
  case("rev_0to10_mean", "data_zero_ten.csv", "zero_ten", c("a", "b", "c"), "b", c(0, 10), "mean"),
  case("frac_sum_every", "data_frac.csv", "frac", FS),
  case("frac_mean_at_2", "data_frac.csv", "frac", FS, statistic = "mean", rule = "at_least 2"),
  case("rev_frac_negative_sum", "data_frac.csv", "frac", FS, c("f1", "f4"), c(-2.5, 3.75), "sum", "at_least 3"),
  case("rev_frac_negative_mean", "data_frac.csv", "frac", FS, "f2", c(-2.5, 3.75), "mean", "at_least 1"),
  case("codes_ticked_sum", "data_codes.csv", "codes", CS, codes = c(-9, 99)),
  case("codes_ticked_mean_at_2", "data_codes.csv", "codes", CS, statistic = "mean", rule = "at_least 2", codes = c(-9, 99)),
  case("codes_unticked_sum", "data_codes.csv", "codes", CS),
  case("codes_one_ticked_mean_at_1", "data_codes.csv", "codes", CS, statistic = "mean", rule = "at_least 1", codes = 99),
  case("codes_outside_ends_reversed", "data_codes.csv", "codes", CS, c("c1", "c3"), c(1, 5), "mean", "at_least 2", c(-9, 99)),
  case("reversed_outside_refused", "data_codes.csv", "codes", CS, "c2", c(1, 5), refused = "reversed_outside_scale"),
  case("counted_every", "data_counted.csv", "counted", Q4),
  case("counted_at_1", "data_counted.csv", "counted", Q4, rule = "at_least 1"),
  case("counted_at_2", "data_counted.csv", "counted", Q4, statistic = "mean", rule = "at_least 2"),
  case("counted_at_3", "data_counted.csv", "counted", Q4, rule = "at_least 3"),
  case("two_sum_every", "data_two.csv", "two", c("x", "y")),
  case("two_mean_at_1", "data_two.csv", "two", c("x", "y"), statistic = "mean", rule = "at_least 1"),
  case("offset_mean", "data_offset.csv", "offset", c("p1", "p2", "p3"), statistic = "mean"),
  case("offset_sum", "data_offset.csv", "offset", c("p1", "p2", "p3")),
  case("cancel_sum", "data_cancel.csv", "cancel", c("m1", "m2", "m3")),
  case("cancel_mean", "data_cancel.csv", "cancel", c("m1", "m2", "m3"), statistic = "mean"),
  case("overflow_sum", "-", "overflow", c("o1", "o2", "o3"), rule = "at_least 2"),
  case("overflow_mean", "-", "overflow", c("o1", "o2", "o3"), statistic = "mean", rule = "at_least 2"),
  case("no_row_refused", "data_no_row.csv", "no_row", c("a", "b"), refused = "no_row_scored"),
  case("k127_sum", "data_k127.csv", "k127", sprintf("w%03d", 1:127), rule = "at_least 100"),
  case("k127_mean_at_top", "data_k127.csv", "k127", sprintf("w%03d", 1:127), statistic = "mean", rule = "at_least 126"),
  case("k128_too_wide", "data_k128.csv", "k128", sprintf("w%03d", 1:128), refused = "too_wide"),
  case("big_sum", "-", "big", BS, rule = "at_least 3"),
  case("big_mean_reversed", "-", "big", BS, c("b2", "b4"), c(0, 130), "mean", "at_least 4")
)

# ---- the score ---------------------------------------------------------------

score_of <- function(cs) {
  X <- as.matrix(data[[cs$key]][, cs$items, drop = FALSE])
  storage.mode(X) <- "double"
  X[X %in% cs$codes] <- NA
  for (it in cs$reversed) {
    j <- match(it, cs$items)
    X[, j] <- cs$scale[1] + cs$scale[2] - X[, j]
  }
  k <- ncol(X)
  n <- if (cs$rule == "every_item") k else as.integer(sub("at_least ", "", cs$rule))
  valid <- rowSums(!is.na(X))
  total <- rowSums(X, na.rm = TRUE)
  avg <- rowMeans(X, na.rm = TRUE)
  raw <- if (cs$statistic == "sum") total else avg
  score <- ifelse(valid >= n, raw, NA)
  overflow <- valid >= n & !is.finite(raw)
  ok <- valid >= n & is.finite(raw)
  list(
    score = score, valid = valid, k = k, n = n, overflow = overflow, ok = ok,
    total_over_count = ifelse(valid > 0, total / valid, NA)
  )
}

rows <- character()
counts <- character()
refused <- character()
measured <- character()
differs_from_total_over_count <- 0L
for (cs in cases) {
  s <- score_of(cs)
  if (!is.null(cs$refused)) {
    size <- sum(s$ok)
    refused <- c(refused, paste(cs$name, cs$refused, size, sep = "\t"))
    next
  }
  every <- sum(s$ok & s$valid == s$k)
  fewer <- sum(s$ok & s$valid < s$k)
  too_few <- sum(s$valid < s$n)
  over <- sum(s$overflow)
  stopifnot(every + fewer + too_few + over == length(s$score))
  counts <- c(counts, paste(cs$name, every, fewer, too_few, over, num(sum(as.numeric(which(s$ok)))), sep = "\t"))
  shown <- if (cs$key == "big") as.integer(seq(1, length(s$score), by = 100)) else seq_along(s$score)
  v <- s$score[shown]
  text <- ifelse(is.na(v), "NA", ifelse(is.infinite(v), "Inf", num(v)))
  rows <- c(rows, paste(cs$name, shown, text, sep = "\t"))
  if (cs$statistic == "mean") {
    same <- s$score[s$ok] == s$total_over_count[s$ok]
    differs_from_total_over_count <- differs_from_total_over_count + sum(!same)
  }
}
measured <- c(measured, sprintf(
  "rowMeans against rowSums / count, over every mean row scored: %d differ (R's own mean is total over count here)",
  differs_from_total_over_count
))

# R's descriptive numbers on one score column per statistic, for the summary.
summaries <- character()
for (name in c("likert_mean_at_3", "frac_sum_every", "rev_0to10_sum", "offset_mean")) {
  cs <- Filter(function(x) x$name == name, cases)[[1]]
  s <- score_of(cs)
  v <- s$score[s$ok]
  summaries <- c(summaries, paste(name, length(v), num(mean(v)), num(sd(v)), num(min(v)), num(max(v)), sep = "\t"))
}

# ---- the files ---------------------------------------------------------------

writeLines(c(
  OUT, VERSION, "case\tfile\titems\treversed\tscale\tstatistic\trule\tmissing_codes",
  vapply(cases, function(cs) paste(
    cs$name, cs$file, paste(cs$items, collapse = " "),
    if (length(cs$reversed)) paste(cs$reversed, collapse = " ") else "-",
    if (is.null(cs$scale)) "-" else paste(num(cs$scale), collapse = " "),
    cs$statistic, cs$rule,
    if (length(cs$codes)) paste(num(cs$codes), collapse = " ") else "-",
    sep = "\t"
  ), "")
), path("cases.tsv"))
writeLines(c(OUT, VERSION, "case\trow\tscore", rows), path("rows.tsv"))
writeLines(c(OUT, VERSION, "case\tevery\tfewer\ttoo_few\toverflow\tscored_rows_sum", counts), path("counts.tsv"))
writeLines(c(OUT, VERSION, "case\tcode\trows_r_scores", refused), path("refused.tsv"))
writeLines(c(OUT, VERSION, "case\tn\tmean\tsd\tmin\tmax", summaries), path("summary.tsv"))
writeLines(c(
  "# The IEEE 754 bits of every number R read, for gaply_core's scale score golden fixtures (Research OS, Phase 8M).",
  "# Generated by /usr/local/bin/Rscript make_prep_fixtures.R (do not edit by hand).",
  VERSION,
  "data,row,column,bits",
  unlist(cell_bits)
), path("cells_bits.csv"))
writeLines(c(OUT, VERSION, measured), path("measurements.txt"))
cat(sprintf("cases %d, rows %d, cells %d\n", length(cases), length(rows), length(cell_bits)))
